public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Adds 2-10 messages grouped together into an album to a quick reply shortcut. Currently, only audio, document, photo and video messages can be grouped into an album.
    /// Documents and audio files can be only grouped in an album with messages of the same type. Returns sent messages
    /// </summary>
    public Task<TdLib.TdApi.Objects.QuickReplyMessages> AddQuickReplyShortcutMessageAlbumAsync(string shortcutName = default, long replyToMessageId = default, InputMessageContent[] inputMessageContents = default)
    {

           using var activity =  StartCallActivity("AddQuickReplyShortcutMessageAlbumAsync", typeof(AddQuickReplyShortcutMessageAlbum).FullName ?? "AddQuickReplyShortcutMessageAlbumAsync");

           try
           {
             return client.AddQuickReplyShortcutMessageAlbumAsync(shortcutName, replyToMessageId, inputMessageContents);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
